const chapters = [
  {id:'face',name:'Face & harmony',tag:'01',desc:'Understand balance, features and healthy presentation.',lessons:[['Facial proportions explained','Use proportions as visual references for styling, never as a score.','Take one neutral photo from a normal distance.','Use hair, glasses and facial hair to frame the whole face.'],['Facial symmetry without obsession','Small left-right differences are normal and usually unnoticed.','Check in soft daylight with a relaxed expression.','Avoid repeated checking and focus on grooming, posture and confidence.'],['Jawline presentation','Definition is affected by structure, soft tissue, light and camera distance.','Keep your head and jaw relaxed.','Use a haircut, beard outline or photo setup before extreme methods.'],['Eye-area grooming','The eye area looks best when clean, rested and naturally framed.','Avoid rubbing and keep tools clean.','Groom brows conservatively and manage sleep or irritation first.'],['Smile presentation','A relaxed smile, clean teeth and healthy gums are high-impact details.','Brush gently with fluoride toothpaste.','Clean between teeth daily and see a dentist for pain or bleeding.']]},
  {id:'hair',name:'Hair & facial hair',tag:'02',desc:'Choose cuts, care and facial-hair shapes that suit your real texture.',lessons:[['Understand your hair texture','Texture, density and growth direction decide how a cut will behave.','Observe clean air-dried hair.','Choose a realistic style and use minimal product.'],['Choosing a practical haircut','A useful haircut suits your hair and your available styling time.','Bring references with similar texture.','Ask how it will sit without product before cutting more.'],['Hairline presentation','A haircut can frame the hairline without hiding every feature.','Work with density and natural growth.','Seek dermatology advice for sudden or progressive loss.'],['Dandruff and scalp care','Flakes and itch need scalp-focused care, not endless styling products.','Inspect for redness, soreness and buildup.','Follow suitable treatment directions and seek help if it persists.'],['Beard neckline placement','A clean neckline creates definition without looking artificial.','Start conservatively and trim in small passes.','Keep tools clean and soothe irritation before repeating.']]},
  {id:'skin',name:'Skin & grooming',tag:'03',desc:'Build a simple, comfortable routine before adding extra products.',lessons:[['Understanding skin types','Skin can be oily, dry or mixed, and it can change with weather or products.','Observe clean skin for thirty minutes.','Choose a simple cleanser, moisturizer and daytime sun protection.'],['Gentle cleansing','Clean skin without stripping it or chasing a squeaky feeling.','Use lukewarm water and fingertips.','Pat dry and moisturize if skin feels tight.'],['Sunscreen without confusion','Daily sun protection supports long-term skin health and even tone.','Use broad-spectrum SPF 30+ on exposed skin.','Reapply after sweating or as the label directs.'],['Acne basics and professional care','Acne needs patience and gentle, evidence-aware treatment.','Add one treatment at a time.','Do not pick; get help for painful, scarring or persistent acne.'],['Shaving without unnecessary irritation','A close shave should not leave burning or repeated ingrown hairs.','Soften hair and use lubrication.','Use light passes and a clean blade.']]},
  {id:'body',name:'Body & posture',tag:'04',desc:'Improve comfort, fitness and silhouette with realistic training.',lessons:[['Comfortable standing posture','Posture is a moving range, not one rigid pose.','Stack head, ribs and pelvis gently.','Breathe normally and move regularly.'],['Desk-friendly sitting posture','Your setup should make frequent movement easier.','Raise the screen and support your feet.','Change position and take short breaks.'],['Beginner full-body workout','Strength grows through controlled practice and recovery.','Choose a variation you can control.','Add difficulty only when form and recovery are stable.'],['Mobility versus flexibility','Mobility is control through range, not forcing deeper stretches.','Use a comfortable range with steady breathing.','Stop for sharp pain, numbness or dizziness.'],['Balanced nutrition basics','Food supports energy, training, skin and hair.','Build meals around protein, produce and enough energy.','Avoid crash diets and deliberate dehydration.']]},
  {id:'style',name:'Style & fashion',tag:'05',desc:'Use fit, colour and context to create repeatable outfits.',lessons:[['Why clothing fit comes first','Fit is read before brand, trend or price.','Check shoulders, waist, length and movement.','Alter a promising piece instead of sizing by the label.'],['Color matching made simple','Good colour works through balance and repetition.','Start with one neutral base.','Add one controlled contrast near the face.'],['Choosing trousers and jeans','Rise, seat, leg line and hem change the whole silhouette.','Sit, walk and bend before judging fit.','Match the break to the shoe and occasion.'],['Jackets and layering','A layer should add shape without restricting movement.','Check the shoulder and closure first.','Keep the layers compatible in thickness.'],['Shoes that complete an outfit','Shoes connect the outfit to the ground and set formality.','Check toe room and heel hold.','Match the shoe weight to your trousers.']]},
  {id:'life',name:'Lifestyle & photo',tag:'06',desc:'Make everyday habits and photography work for you.',lessons:[['Build a consistent sleep schedule','A stable sleep window supports energy and a rested appearance.','Keep wake time reasonably consistent.','Reduce stimulation and light before bed.'],['Hydration without extremes','Normal hydration supports health; dehydration is not a beauty tool.','Drink to thirst and activity.','Do not restrict water for a sharper photo.'],['Camera distance and lens distortion','A close wide lens can change face proportions dramatically.','Step back and use modest zoom.','Keep the camera near eye height.'],['Find soft flattering light','Light shapes the face more than most filters.','Face soft directional daylight.','Avoid harsh overhead shadows and extreme editing.'],['Natural social photos','The best photo looks like you on a good, normal day.','Use a relaxed expression and simple background.','Choose context-appropriate clothing and a representative angle.']]},
  {id:'mind',name:'Confidence & myths',tag:'07',desc:'Build presence while filtering out unsafe online claims.',lessons:[['Confidence through kept promises','Confidence grows from action and evidence you can trust.','Choose one observable behaviour.','Track participation instead of rating your appearance.'],['Comfortable eye contact','Good eye contact is relaxed and responsive, not a stare.','Look briefly, then return attention to the conversation.','Practice in low-pressure situations.'],['Mewing: what it can and cannot do','Comfortable oral posture is different from forced face reshaping.','Keep your jaw relaxed.','Avoid force, clenching and devices; seek care for symptoms.'],['Spotting fake transformations','Before-and-after photos can change through light, lens, pose and editing.','Check the exact conditions shown.','Do not treat dramatic photos as proof of a method.'],['Your worth is not your appearance','Self-improvement should increase participation, not shrink your life.','Notice compulsive checking or avoidance.','Seek qualified mental-health support if appearance distress persists.']]}
  ,{id:'asymmetry',name:'Asymmetry & balance',tag:'08',desc:'Understand normal facial differences and focus on practical balance, not perfection.',lessons:[['What facial asymmetry means','Most faces have small left-right differences. This is normal.','Use a relaxed photo in soft light when checking your face.','Focus on grooming, posture and sleep instead of trying to force bone changes.'],['Reduce tension, not your face','Jaw and neck tension can make an expression look uneven or tired.','Unclench your teeth and let your jaw rest comfortably.','See a clinician for jaw clicking, locking or persistent pain.'],['Use styling to create balance','Hair, glasses, beard shape and photo angle can create a balanced overall impression.','Make one small styling change and compare it in normal daylight.','Avoid obsessive checking or harsh self-judgment.']]},
  {id:'jaw',name:'Jawline & chin',tag:'09',desc:'Learn what changes jawline appearance safely and what methods to avoid.',lessons:[['What creates jawline definition','Bone structure, body composition, posture, hair, facial hair and lighting all affect jawline appearance.','Keep your neck long and jaw relaxed in photos.','Do not hit, press or force your facial bones.'],['Facial-hair framing','A well-placed beard or stubble line can add structure without changing your face.','Start with a conservative neckline and clean cheek line.','Stop if shaving causes persistent irritation or ingrown hairs.'],['Safe oral posture','Comfortable nasal breathing and a relaxed jaw are enough for most people.','Keep your jaw loose and avoid clenching.','Get professional care for chronic mouth breathing, pain or bite concerns.']]},
  {id:'eyes',name:'Eye area',tag:'10',desc:'Use rest, gentle care and conservative grooming for a fresher eye area.',lessons:[['Rested eye-area basics','Sleep, allergies, irritation and sun exposure can affect the eye area.','Keep a reasonably consistent sleep schedule.','Do not use harsh products close to your eyes.'],['Eyebrow shape and maintenance','Brows frame the eyes best when their natural shape is kept intact.','Trim or remove only obvious stray hairs in good light.','Avoid over-plucking or chasing identical brows.'],['Temporary puffiness','Morning puffiness often settles with time and gentle care.','Use a clean cool compress for a few minutes.','Seek medical advice for painful, severe, one-sided or persistent swelling.']]},
  {id:'nutrition',name:'Essential nutrients',tag:'11',desc:'Support energy, skin, hair and training through regular, varied meals.',lessons:[['Build a balanced plate','Nutrition supports health and appearance over time; it is not a fast cosmetic fix.','Include protein, vegetables or fruit, carbohydrates and a healthy fat source.','Avoid crash diets, detoxes and dehydration.'],['Protein, iron and healthy fats','Varied foods help cover normal body needs.','Choose foods you enjoy such as eggs, dairy, beans, fish, meat, nuts or seeds.','Ask a clinician before using high-dose supplements.'],['When to get expert help','Persistent fatigue, hair shedding or restrictive eating deserve professional care.','Speak with a qualified doctor or dietitian.','Do not self-treat a possible deficiency from social-media advice.']]},
  {id:'lips',name:'Lips & smile care',tag:'12',desc:'Keep lips comfortable and your smile healthy with simple habits.',lessons:[['Simple lip care','Lips need gentle protection, especially in dry weather or sun.','Use a plain lip balm when they feel dry.','Avoid picking, scrubbing or irritating fragranced products.'],['A healthy smile','Clean teeth and gums have more impact than aggressive whitening trends.','Brush twice daily with fluoride toothpaste and clean between teeth.','See a dentist for bleeding gums, pain, sensitivity or cosmetic decisions.'],['Natural smile presentation','A relaxed expression photographs better than forcing a perfect smile.','Practice a soft, comfortable smile once.','Do not over-edit photos or compare your smile to filters.']]},
  {id:'conclusion',name:'Build your own guide',tag:'13',desc:'Choose safe changes that make you feel more prepared and comfortable.',lessons:[['Choose your highest-impact basics','A few consistent basics matter more than dozens of hacks.','Start with grooming, clothing fit, sleep and sun protection.','Change one thing at a time so you know what works.'],['Track comfort, not perfection','The useful goal is feeling ready for life, not achieving an impossible ideal.','Save outfits, cuts and routines that work for you.','Take breaks from comparison content when it affects your mood.'],['Know when to ask for help','Professional advice is valuable for pain, skin disease, dental issues or body-image distress.','Contact a qualified clinician for a real assessment.','Avoid unsafe devices, injections and self-treatment methods.']]}
  ,{id:'intro',name:'Introduction to looksmaxing',tag:'14',desc:'Learn what practical self-improvement can change and what it cannot.',lessons:[['Purpose of the guide','Looksmaxing should mean improving grooming, health habits, style and presentation—not chasing a perfect face.','Choose improvements that make daily life easier and more comfortable.','Do not judge yourself by online ratings or filtered photos.'],['Genetics and environment','Genetics influence bone structure, hair texture and many features. Environment and habits affect skin health, grooming and presentation.','Work with your natural features instead of trying to force permanent changes.','Avoid anyone promising guaranteed facial restructuring.'],['Start with the basics','The best starting points are sleep, gentle skincare, dental hygiene, hair care and clothing fit.','Pick one area and keep it simple for two weeks.','Do not start multiple strong products or extreme methods at once.']]},
  {id:'advanced',name:'Advanced & experimental methods',tag:'15',desc:'Understand common online claims, their limits and when professional help is appropriate.',lessons:[['Mewing and orthotropics','Normal oral posture matters for comfort and breathing, but forceful mewing does not safely reshape an adult face.','Keep the jaw relaxed and breathe comfortably through the nose when possible.','Do not hard-mew, clench or use painful devices.'],['Chewing and masseter training','Chewing is normal; excessive gum or resistance training can irritate the jaw joint and muscles.','Use normal meals and stop if you develop clicking, headache or pain.','Do not treat jaw pain as a training signal.'],['Bonesmashing and injections','Hitting facial bones and using hormones or IGF-1 for appearance are dangerous and not home treatments.','Avoid these methods completely.','Discuss medical or surgical concerns only with qualified licensed clinicians.'],['Surgery and professional options','Some concerns, such as bite issues, acne scarring or hair loss, may have clinical options.','Book a proper consultation and ask about benefits, limits, cost and recovery.','Never buy injectable products or procedures from unverified sources.']]},
  {id:'presentation',name:'Grooming & presentation',tag:'16',desc:'Bring hair, beard, brows, clothing and body language into one clear everyday look.',lessons:[['Hair types and care','Straight, wavy, curly and coily hair all need different amounts of cleansing, conditioning and styling support.','Choose products and a haircut that suit your real texture.','Do not copy a routine designed for a very different hair type.'],['Hair and face shape','Hair can frame the face by adding height, softness or structure where you prefer it.','Show your barber references with similar texture and density.','Choose a cut you can realistically maintain.'],['Eyes, brows and facial hair','Conservative brow grooming and clean beard lines can frame the face without looking artificial.','Use clean tools and make small changes.','Avoid over-plucking or creating sharp lines that do not suit your growth pattern.'],['Clothing and presence','Fit, cleanliness, good posture and a calm manner make an outfit feel intentional.','Prepare one reliable outfit formula for common occasions.','Do not buy trends that feel uncomfortable or unlike you.']]}
  ,{id:'foundations',name:'Foundations of attractiveness',tag:'17',desc:'A practical framework for improving presentation without treating looks as a score.',lessons:[['What shapes first impressions','Attractiveness is influenced by health, grooming, expression, style, context and personal preference.','Work on the parts you can control: hygiene, fit, posture and social ease.','Do not reduce yourself or other people to a rating.'],['Base versus modifiers','Your base includes natural features and health; modifiers include hair, skin care, clothing and photos.','Start with high-impact modifiers before spending money on complicated methods.','Do not expect modifiers to permanently change bone structure.'],['Halo effect and facial harmony','People often form a positive overall impression when grooming, clothing and confidence feel coherent.','Aim for clean, consistent presentation instead of a single perfect feature.','Avoid comparing one close-up feature to edited images.'],['Softmaxxing, hardmaxxing and 80/20','Soft changes are reversible habits; medical or surgical changes need expert assessment. The 80/20 approach means prioritize the few basics that matter most.','Choose sleep, skin protection, haircut, dental hygiene and clothing fit first.','Avoid extreme, irreversible or painful shortcuts.']]},
  {id:'aesthetics',name:'Facial aesthetics — theory',tag:'18',desc:'Use facial-aesthetics ideas as styling references, not fixed beauty rules.',lessons:[['Features in context','Jawline, cheeks, eyes, nose and skin are seen together, not as separate scores.','Improve the whole presentation before focusing on one feature.','Do not assume a single feature determines attractiveness.'],['Photos versus real life','Camera distance, lens, light, pose and editing can alter facial proportions.','Use normal-distance photos in soft light for a fairer view.','Do not use one selfie as evidence that something is wrong.'],['Cheekbones, eyes and nose','These features are largely structural; styling can change emphasis but not safely reshape them at home.','Use hair, glasses and light to create your preferred balance.','Avoid devices or exercises marketed as permanent facial restructuring.']]},
  {id:'frame',name:'Body & frame',tag:'19',desc:'Build strength, posture and a healthy body composition through sustainable training.',lessons:[['Proportions and priority muscles','Aesthetic goals vary, but legs, back, chest, shoulders and arms all benefit from balanced training.','Use full-body movements with good technique and recovery.','Do not neglect legs or train through joint pain.'],['Beginner training and progression','A beginner plan can use two to four full-body sessions per week. Progress means slowly adding repetitions, load or control.','Start with exercises you can perform safely and consistently.','Do not copy a five-day split before you can recover from it.'],['Body fat and facial appearance','Body composition can change how facial features look, but health matters more than getting very lean.','Use gradual nutrition and training habits if fat loss is appropriate for you.','Avoid crash diets, dehydration or appearance-driven overtraining.'],['Hydration and fat-loss timelines','Hydration supports normal function; it is not a rapid sculpting tool. Sustainable body changes take months, not days.','Eat regular meals and drink according to thirst and activity.','Do not cut water or use diuretics for photos.']]},
  {id:'skincomplete',name:'Skincare — complete guide',tag:'20',desc:'Build a simple routine, introduce one active at a time and seek help for persistent acne.',lessons:[['Cleanse, treat and protect','The core routine is gentle cleansing, moisturizer when needed and broad-spectrum SPF 30+ sun protection.','Keep the routine simple for several weeks before changing it.','Do not scrub or stack many strong products.'],['Active ingredients','Retinoids, salicylic acid, benzoyl peroxide and azelaic acid can help different acne concerns; vitamin C, niacinamide and AHAs may irritate some skin.','Introduce one active slowly and follow its label.','Stop and seek advice if you get severe irritation, swelling or worsening symptoms.'],['Acne treatment ladder','Start with gentle basics and an appropriate over-the-counter active; persistent, painful or scarring acne needs a dermatologist.','Give a well-tolerated routine time to work.','Do not pick acne or use toothpaste, harsh scrubs or unverified hacks.'],['Under-eye care','Sleep, allergies, irritation and sun exposure affect the under-eye area.','Use gentle products and a cool compress for temporary puffiness.','Seek medical advice for pain, vision changes or one-sided swelling.']]},
  {id:'haircomplete',name:'Hair — complete guide',tag:'21',desc:'Match haircuts and care routines to your hair type, face shape and real maintenance time.',lessons:[['Face shape and haircut matching','Face shape can help narrow ideas, but texture, density and growth pattern matter more.','Show a barber reference with similar hair texture.','Do not choose a cut only because it suits someone with very different hair.'],['Hair health and styling products','Use a routine that cleans the scalp, conditions lengths when needed and uses a small amount of suitable styling product.','Test product amount on clean, dry or damp hair as directed.','Do not overload hair with oil, wax or heat.'],['Hair loss treatments','Pattern hair loss can have medical options such as minoxidil or finasteride, but suitability and risks must be discussed with a clinician.','Seek a dermatologist or qualified doctor for a diagnosis.','Do not buy prescription treatments from unverified sellers.'],['Beard and eyebrow grooming','Keep your natural growth pattern and clean tools.','Use small trimming changes, then reassess in daylight.','Avoid over-plucking brows or sharply outlining a beard that you cannot maintain.']]},
  {id:'hormones',name:'Hormones & physical development',tag:'22',desc:'Protect normal development and avoid online hormone manipulation advice.',lessons:[['Hormones and appearance','Hormones affect many body systems, but appearance changes are not a reason to self-medicate.','Support health with sleep, food, activity and stress management.','Do not use testosterone, growth hormone or research chemicals without medical supervision.'],['Puberty and sleep','Puberty timing varies widely. Consistent sleep supports recovery, mood and normal development.','Keep a regular wake time and reduce late-night stimulation.','Do not compare your timeline to influencers or peers.'],['Alcohol, nicotine and cannabis','These can affect sleep, fitness, mood and health, especially for young people.','Choose supportive social habits and seek help if stopping is difficult.','Do not treat substances as confidence or stress solutions.']]},
  {id:'supplements',name:'Supplements — practical database',tag:'23',desc:'Supplements are optional; food, sleep and training come first.',lessons:[['Core principle','A supplement cannot replace a balanced diet, sleep or a sensible training plan.','Use food-first habits and speak to a clinician for suspected deficiency.','Do not use large doses, mystery blends or multiple overlapping products.'],['Common performance supplements','Creatine, vitamin D, magnesium, zinc and omega-3 are often discussed, but need depends on diet, health and local guidance.','Check with a qualified clinician or pharmacist before starting one.','Do not use supplement stacks as a teenager without professional advice.'],['Skin, sleep and stress claims','Many beauty, collagen, ashwagandha and sleep products have mixed evidence or interaction risks.','Prioritize a simple routine and ask a pharmacist about interactions.','Do not use supplements to treat anxiety, insomnia or acne without care.']]},
  {id:'medical',name:'Surgical & medical interventions',tag:'24',desc:'Medical decisions need qualified assessment, informed consent and realistic expectations.',lessons:[['When to consider care','Consider professional care for functional concerns, persistent skin disease, bite issues, hair loss or distress that affects your life.','Start with a licensed doctor, dentist or dermatologist.','Do not decide from a before-and-after photo alone.'],['Choosing a qualified professional','Check licensing, relevant experience, risks, recovery and follow-up care.','Get a second opinion for elective procedures.','Avoid providers who pressure you or promise perfection.'],['Procedure overview and limits','Treatments can address specific concerns but have cost, recovery, side effects and limits.','Ask what happens if the result is not as expected.','Never perform procedures, fillers or injections at home.']]},
  {id:'mindset',name:'The mental side & final summary',tag:'25',desc:'Use self-improvement to participate more in life, not to become trapped by appearance.',lessons:[['Step away from blackpill thinking','Fatalistic appearance beliefs can harm mood and stop useful action.','Focus on learnable skills, health and kind self-talk.','Seek mental-health support if appearance thoughts feel constant or distressing.'],['Build a simple stack','A useful routine is short: sleep, food, movement, grooming and prepared clothes.','Add one habit only after the previous one feels automatic.','Do not turn every hour into an optimization project.'],['Highest-leverage changes','The six basics are sleep, sun protection, dental hygiene, movement, simple nutrition and clothing fit.','Make a one-page checklist for your own week.','Do not chase perfection; consistency beats intensity.']]}
];
const quickTips=[['01','Use daylight','Judge skin, hair and outfits in indirect daylight before making a decision.'],['02','Fit before brand','A simple garment that fits well beats an expensive one that pulls or hangs.'],['03','Keep tools clean','Clean clippers, razors, brushes and pillowcases help prevent irritation and buildup.'],['04','One change at a time','A simple routine makes it clear what is helping and what is irritating.'],['05','Step back from the camera','A farther camera distance gives a fairer view of facial proportions.'],['06','Relax the jaw','Clenching can create tension and does not safely build a jawline.'],['07','Save working outfits','Photograph outfits that feel good so dressing becomes easier.'],['08','Prioritize sleep','A consistent sleep schedule helps energy, mood and a rested appearance.'],['09','Use sun protection','Comfortable broad-spectrum sunscreen is a long-term grooming essential.'],['10','Move often','Posture improves through movement, not holding one rigid position all day.'],['11','Clean shoes matter','A clean, well-kept pair is more noticeable than an extra trend piece.'],['12','Use a gentle cleanse','Over-washing and scrubbing can irritate skin and worsen the problem.']];
const styleCards=[['The clean-base wardrobe',['Well-fitting tees or shirts','Straight trousers or jeans','A versatile outer layer','Clean everyday footwear']],['Colour formula',['Start with navy, charcoal, cream, olive or brown','Add one accent','Repeat a colour once','Check it in daylight']],['Fit checkpoints',['Shoulder seam','Waist comfort','Sleeve and trouser length','Comfort while walking and sitting']],['Smart-casual formula',['Fitted knit or polo','Clean trousers','Minimal leather sneaker or loafer','One structured layer']],['Accessories',['One watch or simple ring','Match metals loosely','Use a belt that suits footwear','Avoid adding everything at once']],['Care makes style',['Steam or press garments','Remove lint','Repair small damage','Store shoes and knits properly']]];
const topicSeeds=chapters.flatMap(c=>c.lessons.map(l=>[c.name,l[0],l[1],l[2],l[3]]));
const questionStarts=['How do I start with','What should I know about','What is the safest way to improve','How often should I work on','What mistakes should I avoid with','What results are realistic for','Can I improve','How can I check','When should I get help with','What is one useful tip for'];
const faqs=Array.from({length:500},(_,i)=>{const [cat,title,summary,step,tip]=topicSeeds[i%topicSeeds.length];const q=`${questionStarts[Math.floor(i/topicSeeds.length)%questionStarts.length]} ${title.toLowerCase()}?`;return{cat,q,short:summary,answer:`${summary} ${step} ${tip} Keep changes comfortable, gradual and easy to repeat.`,tips:[step,tip,'Review progress in normal conditions, not one close selfie.']}});
faqs.unshift(...[
  {cat:'Face & harmony',q:'How do skin clarity, eyebrows, and teeth affect overall facial balance?',short:'These details frame the face and strongly affect how polished and healthy you look.',answer:'Clear, comfortable skin, naturally groomed brows and healthy teeth improve the overall impression without changing your face. Aim for care and consistency rather than perfection.',tips:['Use gentle skincare and daily sun protection.','Groom brows conservatively.','Brush twice daily, clean between teeth and see a dentist for pain or bleeding.']},
  {cat:'Asymmetry & balance',q:'What practical steps improve facial symmetry?',short:'Most asymmetry is normal; grooming, relaxed posture and dental or medical care for real concerns are the practical options.',answer:'Use soft-light photos, maintain a relaxed jaw, choose balanced hair or facial-hair styling, and seek professional dental or medical advice for pain, bite problems or sudden changes.',tips:['Avoid obsessive mirror checking.','Do not force exercises to reshape bone.','Use styling to improve the overall balance.']},
  {cat:'Jawline & chin',q:'Does mewing or chewing realistically change jawline definition?',short:'Comfortable oral posture is fine, but forceful mewing or chewing is not a reliable way to reshape an adult jaw.',answer:'Jawline appearance is mostly affected by natural structure, body composition, facial hair, posture, lighting and camera distance. Excessive chewing can irritate the jaw joint.',tips:['Keep the jaw relaxed.','Use haircut or beard framing first.','See a dentist or clinician for pain, clicking or bite concerns.']},
  {cat:'Advanced & experimental methods',q:'Which jawline methods are safe versus risky?',short:'Normal grooming and relaxed posture are low-risk; bonesmashing, hormone or IGF-1 injections and painful devices are high-risk.',answer:'Never hit facial bones or use hormones for appearance without a licensed clinician. Medical care is appropriate only for diagnosed concerns and after informed discussion.',tips:['Avoid bonesmashing completely.','Do not buy injections online.','Choose qualified professional assessment for medical concerns.']},
  {cat:'Hair & facial hair',q:'Which hairstyles suit different face shapes?',short:'The best haircut depends on hair texture, density, growth pattern and maintenance time as much as face shape.',answer:'Use face shape only as a starting point. Take references with hair similar to yours and ask a barber how the style behaves without heavy product.',tips:['Match references to your texture.','Choose a cut you can maintain.','Review the cut in normal light before making a big change.']},
  {cat:'Hair — complete guide',q:'How do I maintain healthy hair and address hair loss?',short:'Use scalp-appropriate care and get a professional assessment for progressive shedding or pattern loss.',answer:'Hair health benefits from gentle scalp care, suitable conditioning and avoiding excessive heat or harsh styling. Hair loss can have many causes; a clinician can assess options such as minoxidil or finasteride where appropriate.',tips:['Avoid unverified hair-loss products.','Use clean tools and a realistic routine.','Get help for sudden or persistent shedding.']},
  {cat:'Eye area',q:'What are “hunter eyes” and how do eyelid or brow position affect attractiveness?',short:'“Hunter eyes” is an online aesthetic label, not a health goal or a feature you should try to force.',answer:'Eye shape and brow position are largely natural. The most useful improvements are rested appearance, conservative eyebrow grooming and good lighting—not devices, taping or exercises.',tips:['Avoid products or tools that irritate the eye.','Keep brows natural.','See an eye-care professional for eyelid, vision or swelling concerns.']},
  {cat:'Eye area',q:'Which grooming techniques enhance the eye area?',short:'Clean tools, natural brows, sleep and sun protection make the eye area look more refreshed.',answer:'Tidy only obvious brow strays, manage allergies or irritation, and avoid rubbing your eyes. Temporary puffiness may settle with a clean cool compress.',tips:['Do not over-pluck.','Avoid harsh products near the eyes.','Seek care for painful or one-sided swelling.']},
  {cat:'Skin & grooming',q:'What daily routine helps prevent acne and maintain clear skin?',short:'Keep the routine simple: gentle cleanser, moisturizer if needed, and broad-spectrum SPF 30+ sunscreen.',answer:'For acne, introduce one evidence-based active such as adapalene, benzoyl peroxide, salicylic acid or azelaic acid slowly and follow the label. Persistent, painful or scarring acne needs a dermatologist.',tips:['Do not pick acne.','Add one active at a time.','Avoid toothpaste, harsh scrubs and miracle cures.']},
  {cat:'Skin & grooming',q:'Which products or nutrients are most useful for long-term skin health?',short:'Sun protection, a gentle routine, adequate food and sleep matter more than expensive product stacks.',answer:'Use products your skin tolerates and eat varied meals with protein, produce and healthy fats. No supplement can replace sun protection or medical treatment for skin disease.',tips:['Use SPF 30+ daily on exposed skin.','Avoid crash diets.','Ask a clinician before high-dose supplements.']},
  {cat:'Lifestyle & photo',q:'How do sleep posture, mattress firmness and exercise affect facial development?',short:'They can affect comfort, sleep and daily posture, but they do not safely remodel an adult face.',answer:'Choose a sleep position and mattress that support comfortable, good-quality sleep. Regular exercise benefits health and posture; avoid claims that sleeping without a pillow or on a hard mattress reshapes your face.',tips:['Prioritize sleep quality.','Move regularly.','See a clinician for chronic pain or breathing problems.']},
  {cat:'Body & posture',q:'What role does diet play in looksmaxxing?',short:'Diet supports energy, skin, hair, training and long-term health, not instant facial changes.',answer:'Regular meals with enough protein, produce, carbohydrates and fats support normal function. If fat loss is appropriate, gradual changes are safer than restriction or dehydration.',tips:['Eat consistently.','Drink to thirst and activity.','Avoid detoxes and crash diets.']},
  {cat:'Essential nutrients',q:'Which vitamins, minerals and proteins support skin, hair and bone health?',short:'Adequate protein and varied foods are the foundation; supplements only help in specific situations.',answer:'Nutrients such as protein, iron, zinc and vitamin D have normal body roles, but need and dosage depend on your diet and health. A clinician can test for suspected deficiency.',tips:['Food first.','Do not combine high-dose products blindly.','Ask a clinician or pharmacist before supplementing.']},
  {cat:'Supplements — practical database',q:'Is collagen supplementation useful or overrated?',short:'Collagen is optional; it is not a shortcut and evidence varies by goal and product.',answer:'Adequate overall protein, sunscreen and a balanced diet are higher priorities. Consider supplements only after checking safety, cost and realistic expectations with a qualified professional.',tips:['Do not expect rapid facial changes.','Check ingredients and interactions.','Avoid replacing meals with supplements.']},
  {cat:'Grooming & presentation',q:'How do beard styles, eyebrow shaping and clothing choices change perception?',short:'They frame the face and silhouette, making your presentation look more intentional.',answer:'A clean beard line, natural brows and well-fitting clothing can create a strong overall impression. Small, consistent adjustments are usually more effective than dramatic changes.',tips:['Fit comes before brand.','Use clean grooming tools.','Choose styles you can maintain.']},
  {cat:'Grooming & presentation',q:'Which grooming habits should be non-negotiable?',short:'Dental hygiene, bathing, clean hair and nails, skin protection, clean clothes and well-kept shoes are the essentials.',answer:'Build a short routine you can repeat: brush and clean between teeth, wash as needed, use deodorant if you choose, keep tools clean and prepare clothes for the next day.',tips:['Keep it simple.','Replace worn grooming tools.','Consistency beats expensive products.']},
  {cat:'Surgical & medical interventions',q:'What are orthotropics and surgical interventions, and when are they considered?',short:'Orthotropics is an orthodontic approach; surgery is considered for specific medical or functional concerns after specialist assessment.',answer:'Neither is a casual cosmetic hack. Bite, breathing, jaw or skin concerns need evaluation by qualified clinicians who can explain benefits, limits, risks and alternatives.',tips:['Seek licensed specialists.','Get a second opinion for elective procedures.','Avoid online diagnosis or home devices.']},
  {cat:'Advanced & experimental methods',q:'Which methods are safe, controversial or high-risk?',short:'Low-risk basics include grooming, sleep, exercise and sun protection; painful reshaping methods and unprescribed drugs are high-risk.',answer:'If a claim promises permanent facial change quickly, treats pain as progress or tells you to self-inject or hit bones, avoid it. Use professional care for medical needs.',tips:['Prefer reversible changes first.','Check evidence and credentials.','Stop any practice that causes pain or distress.']},
  {cat:'The mental side & final summary',q:'How do I balance realistic expectations with long-term consistency?',short:'Choose goals based on comfort, health and participation—not on a perfect appearance.',answer:'Use a small routine, track helpful habits and take breaks from comparison content. Long-term consistency means adjusting the plan when life changes, not forcing perfection.',tips:['Choose one change at a time.','Review monthly, not hourly.','Seek support if appearance anxiety grows.']},
  {cat:'Foundations of attractiveness',q:'Which practices give the biggest return on effort?',short:'The practical 80/20 basics are sleep, sun protection, dental hygiene, movement, regular meals and clothing fit.',answer:'These habits improve wellbeing and everyday presentation together. Add hairstyle, beard or style refinements only after the foundations feel easy to maintain.',tips:['Keep a short checklist.','Prioritize consistency.','Avoid extreme shortcuts.']}
]);
chapters.splice(0,chapters.length,...[
  {id:'foundations',name:'Foundations of Attractiveness',tag:'01',desc:'Understand the controllable foundations before changing anything else.',lessons:[['What Actually Determines Attractiveness','Attractiveness is a whole-person impression shaped by health, grooming, expression, style and context.','Start with sleep, hygiene and clothing fit.','Avoid reducing people to a score.'],['Base vs. Modifiers Framework','Natural features are your base; hair, skin care, style and photos are modifiers.','Improve easy modifiers first.','Do not expect modifiers to reshape bone.'],['Softmaxxing vs. Hardmaxxing','Soft changes are reversible habits; medical changes require professional advice.','Prefer safe, reversible changes.','Avoid permanent decisions from online pressure.'],['The 80/20 Rule','A few basics give most of the result.','Prioritize sleep, dental care, sunscreen, movement, fit and grooming.','Do not chase dozens of hacks.']]},
  {id:'aesthetics',name:'Facial Aesthetics — Theory',tag:'02',desc:'Use facial-aesthetic ideas as references, never as rigid beauty rules.',lessons:[['What the Research Actually Says','Research can describe averages but cannot decide an individual’s value or attractiveness.','Look at the whole face and real-life presence.','Avoid treating ratios as a diagnosis.'],['Feature-by-Feature Breakdown','Jawline, cheekbones, eyes, nose and skin are seen together.','Improve presentation before focusing on one feature.','Do not compare close-ups to edited images.'],['Static Photos vs. Real Life','Lens, distance, light and pose can change how a face appears.','Use normal-distance photos in soft light.','Do not judge yourself from one selfie.']]},
  {id:'mewing',name:'Mewing & Facial Bone Remodeling',tag:'03',desc:'Separate comfortable oral posture from exaggerated online claims.',lessons:[['What the Science Supports','Normal oral posture and nasal breathing can be comfortable, but do not reliably reshape an adult face.','Keep the jaw relaxed.','Avoid promises of permanent rapid change.'],['Comfortable Oral Posture','The goal is comfort, not force.','Keep teeth unclenched and stop if there is pain.','Seek professional care for bite or breathing concerns.'],['Chewing for Jaw Development','Normal chewing is enough; excessive gum can irritate the jaw joint.','Stop if you develop clicking, pain or headaches.','Do not treat pain as progress.'],['Realistic Results by Age — Age-Neutral','Bone growth and development vary by person and age.','Focus on safe habits at every age.','Avoid age-based promises and forced techniques.']]},
  {id:'body',name:'Body & Frame',tag:'04',desc:'Build strength, posture and nutrition habits that are sustainable.',lessons:[['Beginner Training Guide','Start with simple full-body training and steady recovery.','Train two to four times weekly with good form.','Do not train through sharp pain.'],['5-Day Program','A five-day program is optional, not a requirement.','Use it only when sleep, food and recovery are solid.','Do not copy advanced volume too early.'],['Being Overweight & Fat Loss','Gradual changes can support health when appropriate.','Use regular meals, activity and professional help when needed.','Avoid crash diets or dehydration.'],['Nutrition & Hydration','Food and water support energy, skin, hair and training.','Build varied meals and drink to thirst.','Avoid detoxes and diuretics.']]},
  {id:'skin',name:'Skincare — Complete Guide',tag:'05',desc:'Use a simple routine and add targeted treatment carefully.',lessons:[['Sunscreen — Complete Guide','Broad-spectrum SPF 30+ helps protect exposed skin.','Use a comfortable product daily and reapply as directed.','Do not rely on tanning for skin health.'],['Active Ingredients Breakdown','Retinoids, niacinamide, vitamin C, salicylic acid, benzoyl peroxide, azelaic acid and AHAs have different uses and irritation risks.','Add one active slowly and follow the label.','Do not stack strong actives at once.'],['Acne Treatment Ladder','Start gently and seek a dermatologist for painful, scarring or persistent acne.','Use evidence-based products consistently.','Do not pick or use harsh DIY remedies.'],['Under-Eye Area','Rest, allergies, irritation and sun exposure affect the eye area.','Use gentle care and a cool compress for temporary puffiness.','Get care for pain, vision changes or one-sided swelling.']]},
  {id:'hair',name:'Hair — Complete Guide',tag:'06',desc:'Choose hair care and cuts based on your actual texture and maintenance time.',lessons:[['How to Find Your Face Shape','Face shape is only a guide; hair texture and growth pattern matter more.','Use a relaxed photo in normal light.','Do not treat face shape as a score.'],['Matching Haircuts by Shape','A haircut can frame the face, but it must suit your density and texture.','Bring realistic references to a barber.','Avoid styles you cannot maintain.'],['Hair Health','Scalp care, gentle washing and avoiding excessive heat support healthy hair.','Use a simple routine that your scalp tolerates.','Avoid overloading hair with product.'],['Hair Loss Treatment','Hair loss has many causes and may need medical assessment.','Ask a dermatologist about evidence-based options.','Do not self-prescribe finasteride, minoxidil or supplements.']]},
  {id:'hormones',name:'Hormones & Physical Development',tag:'07',desc:'Support normal development and avoid hormone manipulation advice.',lessons:[['Sleep Quality Guide','Consistent sleep supports recovery, mood and normal development.','Keep a stable wake time and wind down before bed.','Do not chase extreme sleep hacks.'],['Puberty Timeline','Puberty timing varies widely.','Discuss concerns with a qualified clinician.','Do not compare your body to influencers.'],['Maximizing Testosterone Safely','Sleep, food, training and stress management support general health.','Use healthy habits instead of hormone products.','Do not use testosterone or growth hormones without care.'],['Alcohol & Drugs — Appearance Impact','Alcohol, nicotine and drugs can affect sleep, health and appearance.','Choose supportive social habits.','Seek help if stopping feels difficult.']]},
  {id:'supplements',name:'Supplements — Complete Database',tag:'08',desc:'Supplements are optional and should never replace food or medical care.',lessons:[['Core Performance Supplements','Creatine, vitamin D, magnesium, zinc and omega-3 are commonly discussed, but need is individual.','Ask a clinician or pharmacist before starting one.','Do not combine high-dose products blindly.'],['Supplements to Avoid as a Teen','Teenagers should not use hormone boosters, stimulant-heavy blends or large stacks.','Speak with a parent or clinician first.','Avoid online products with hidden ingredients.'],['Skin & Sleep Supplements','Collagen, ashwagandha and beauty blends have mixed evidence and possible interactions.','Prioritize food, sunscreen and sleep first.','Do not use supplements to treat acne or anxiety alone.']]},
  {id:'grooming',name:'Grooming & Style',tag:'09',desc:'Create a clean, repeatable presentation for everyday life.',lessons:[['Full Grooming Routine','Keep teeth, hair, skin, nails, body and clothes clean.','Prepare a short routine you can repeat.','Do not buy products you will not use.'],['Cologne','Fragrance should be subtle and optional.','Use one or two light sprays on clean skin or clothes if suitable.','Do not overspray in shared spaces.'],['Posture & Voice','Relaxed posture and clear, comfortable speech improve presence.','Move often and speak at a natural pace.','Do not force a deeper voice or rigid posture.'],['Style & Fashion','Fit, colour and clean shoes do more than trends.','Save reliable outfit formulas.','Do not dress only for online approval.']]},
  {id:'medical',name:'Surgical & Medical Interventions',tag:'10',desc:'Medical decisions deserve specialist advice, time and informed consent.',lessons:[['Before You Consider Any Procedure','Clarify whether your concern is functional, medical or cosmetic.','Start with a licensed professional.','Do not decide from one before-and-after photo.'],['How to Find a Surgeon','Check licensing, specialty experience, risks and follow-up care.','Get a second opinion for elective procedures.','Avoid high-pressure consultations.'],['Procedure Overview Table','Procedures have possible benefits, limits, costs, recovery and risks.','Ask for written information and realistic outcomes.','Never inject or perform procedures at home.']]},
  {id:'mental',name:'The Mental Side',tag:'11',desc:'Keep self-improvement connected to wellbeing, relationships and real life.',lessons:[['What the Blackpill Gets Right','Appearance can affect first impressions, but it is only one part of life.','Use that insight to improve controllable habits.','Do not turn it into fatalism.'],['Where It Goes Wrong','Blackpill thinking can exaggerate appearance and ignore skills, relationships and context.','Challenge all-or-nothing thoughts.','Seek support if comparison becomes distressing.'],['The Ascended Mindset','A healthy mindset values progress, competence and kindness.','Set goals that help you participate more.','Do not make appearance your only identity.']]},
  {id:'routines',name:'Full Routines & Stacking',tag:'12',desc:'Create short, age-appropriate routines without over-optimizing.',lessons:[['Daily Routine: Teen (13–17)','Focus on sleep, school-life balance, hygiene, food and safe movement.','Keep products and supplements simple.','Discuss health concerns with a parent or clinician.'],['Daily Routine: Young Adult (18–25)','Build around sleep, work or study, movement, meals and grooming.','Prepare clothes and meals when helpful.','Do not sacrifice recovery for an extreme routine.'],['Supplement Stack by Age','There is no universal stack. Need depends on diet, health and clinician advice.','Use food-first habits at every age.','Avoid hormone or stimulant products.'],['Skincare Budget Tiers','A budget routine can be cleanser, moisturizer and sunscreen.','Add one active only for a clear purpose.','Do not equate price with effectiveness.']]},
  {id:'summary',name:'Final Summary',tag:'13',desc:'Choose the few habits that create a healthier, more prepared everyday presence.',lessons:[['Highest-Leverage Changes Ranked','Sleep, sun protection, dental hygiene, movement, food and clothing fit are the core wins.','Start with the easiest foundation.','Do not neglect health for a cosmetic shortcut.'],['Six Non-Negotiables','Keep a short list: sleep, hygiene, sun protection, movement, meals and clean clothes.','Make each habit easy to repeat.','Do not punish yourself for imperfect days.'],['Natural Progression','Improve one area, then maintain it before adding another.','Review progress in months, not selfies.','Avoid sudden extreme changes.'],['One-Page Cheat Sheet','Your best guide should fit on one page and fit your actual life.','Write your next three actions.','Keep the plan flexible and kind.']]}
]);
faqs.unshift(...[
  {cat:'Facial Aesthetics — Theory',q:'Why does my face look different from different angles?',short:'Perspective, light, expression and lens distortion all change appearance.',answer:'A close wide-angle phone lens enlarges whatever is nearest to it. Head tilt, shadows, posture and expression also change apparent proportions.',tips:['Compare from a farther camera distance.','Use soft, even light.','Do not judge your face from one selfie.']},
  {cat:'Facial Aesthetics — Theory',q:'How can I make my face look less round?',short:'Use framing and proportion before extreme measures.',answer:'Try a hairstyle with controlled height or angles, intentional facial-hair lines, complementary glasses and clothing necklines that create vertical space. Fat loss cannot be targeted only to the face.',tips:['Choose sustainable health habits.','Use hair and facial-hair framing.','Avoid dehydration and crash diets.']},
  {cat:'Facial Aesthetics — Theory',q:'Can weight loss change nose appearance?',short:'It can change surrounding facial fullness, not nasal bone or cartilage.',answer:'Overall body-composition change may alter cheeks and the way the nose is framed, but nose structure is largely stable.',tips:['Avoid nose clips or pressure.','Use a fair camera distance.','Choose gradual health changes if appropriate.']},
  {cat:'Facial Aesthetics — Theory',q:'What is a recessed midface?',short:'It is an anatomical description that needs professional assessment to define.',answer:'Online photos and camera lenses can make the midface look flatter or more prominent. Do not diagnose yourself from a selfie.',tips:['Use styling and photography for visual balance.','See a qualified professional for bite or breathing concerns.','Avoid self-diagnosis.']},
  {cat:'Facial Aesthetics — Theory',q:'How can I make my cheekbones stand out in photos?',short:'Use soft directional light and a normal lens distance.',answer:'Face light from slightly to the side, keep the camera farther away and use a relaxed expression. Hair and facial-hair framing can add contrast.',tips:['Avoid harsh shadows.','Do not dehydrate for photos.','Keep your expression natural.']},
  {cat:'Facial Aesthetics — Theory',q:'Are hollow cheeks attractive?',short:'There is no universal ideal, and chasing hollowness can harm health.',answer:'Cheek fullness varies with genetics, age and body composition. Healthy skin, expression and proportion matter more than one trend.',tips:['Do not starve or dehydrate.','Avoid unsafe products.','Focus on overall health.']},
  {cat:'Hair — Complete Guide',q:'How do I choose the right haircut?',short:'Match the cut to your texture, density, hairline and daily maintenance time.',answer:'Bring references with similar hair, then ask a barber how the style will grow out and sit without heavy product.',tips:['Choose realistic references.','Ask for maintenance advice.','Do not copy a cut designed for different hair.']},
  {cat:'Hair — Complete Guide',q:'How do I make thin hair look fuller?',short:'Use a suitable cut, lighter product and gentle volume techniques.',answer:'A shorter or textured cut, careful blow-drying and light styling product can add the appearance of volume. Persistent thinning needs clinical assessment.',tips:['Avoid heavy oils and waxes.','Use gentle scalp care.','See a clinician for sudden shedding.']},
  {cat:'Hair — Complete Guide',q:'What should I do about a receding hairline?',short:'Choose a realistic style and seek a professional assessment for progressive loss.',answer:'A cut that works with your hairline often looks stronger than trying to hide it. A dermatologist can discuss possible causes and treatment options.',tips:['Do not buy prescription products from unverified sellers.','Avoid panic-driven treatments.','Use a haircut you can maintain.']},
  {cat:'Grooming & Style',q:'How do I shape a patchy beard?',short:'Use length and clean lines to create coherence; trimming cannot create new follicles.',answer:'Keep the beard at a length that looks even, clear the lip line and choose a conservative neckline. A shorter stubble style can be easier for uneven growth.',tips:['Use clean tools.','Trim in small steps.','Do not over-outline the cheeks.']},
  {cat:'Grooming & Style',q:'Can posture improve my appearance?',short:'Comfortable upright posture can improve presence, but it should not be rigid.',answer:'Posture changes how clothes sit and how you carry yourself. The goal is a comfortable moving range, regular breaks and steady breathing.',tips:['Move often.','Set up your desk comfortably.','Stop for pain, numbness or dizziness.']},
  {cat:'Body & Frame',q:'How do I build broader-looking shoulders?',short:'Train the whole upper body and use clothing fit; do not chase isolated shortcuts.',answer:'Balanced upper-body training can develop the shoulders, back and chest over time. Garment shoulder fit and a clean jacket shape can improve the silhouette immediately.',tips:['Use good technique.','Train legs and back too.','Allow recovery between sessions.']},
  {cat:'Body & Frame',q:'How do I lose face fat?',short:'You cannot target face fat; overall changes occur gradually and vary by person.',answer:'If weight loss is appropriate, use a sustainable food pattern, activity, sleep and enough nutrition. Genetics determine where change appears first.',tips:['Avoid crash diets.','Do not dehydrate.','Measure progress over months.']},
  {cat:'Skincare — Complete Guide',q:'How can I reduce facial redness?',short:'Reduce irritation and identify the underlying cause.',answer:'Use a gentle cleanser, moisturizer and sunscreen. Avoid hot water, harsh scrubs and products that sting. Persistent flushing, burning or rash needs clinical assessment.',tips:['Keep products simple.','Avoid aggressive exfoliation.','Seek care if symptoms persist.']},
  {cat:'Skincare — Complete Guide',q:'How can I reduce acne scars?',short:'Prevent new scars first, then have the scar type assessed.',answer:'Do not pick acne, protect skin from sun and keep active acne controlled. Dark marks and indented scars need different professional approaches.',tips:['Avoid DIY acids and scraping.','Use sunscreen.','See a dermatologist for scarring acne.']},
  {cat:'Full Routines & Stacking',q:'How can I reduce morning facial puffiness?',short:'Use sleep, normal hydration, gentle movement and time.',answer:'Sleep consistently, avoid rubbing and try a clean cool compress for a few minutes. Excess salt can affect some people, but deliberate dehydration is not a solution.',tips:['Hydrate normally.','Do not use direct ice.','Get care for persistent, painful or one-sided swelling.']},
  {cat:'Full Routines & Stacking',q:'Does drinking more water clear skin?',short:'Normal hydration supports health, but extra water alone does not cure acne.',answer:'Drink according to thirst and activity, then use a simple evidence-based skincare routine. Persistent acne needs appropriate treatment or professional care.',tips:['Avoid dehydration.','Do not overdrink water.','Use one treatment consistently.']},
  {cat:'The Mental Side',q:'How can I feel more confident in public?',short:'Confidence grows through participation, skills and repeated real-world experience.',answer:'Choose small social actions, wear an outfit that feels comfortable and focus attention on the conversation rather than constant self-monitoring.',tips:['Start in low-pressure situations.','Keep promises to yourself.','Seek support if anxiety limits daily life.']},
  {cat:'Mewing & Facial Bone Remodeling',q:'Can gua sha permanently sculpt my face?',short:'No—massage may feel relaxing or reduce temporary puffiness, but it does not reshape facial bones.',answer:'Use gentle massage only if it feels comfortable and your skin tolerates it. Any temporary change is not structural.',tips:['Do not press hard.','Avoid broken or irritated skin.','Stop if you bruise or hurt.']},
  {cat:'Mewing & Facial Bone Remodeling',q:'Do jaw exercisers work?',short:'They can overload the jaw and do not safely guarantee a stronger-looking jawline.',answer:'Repeated resistance can contribute to joint or muscle symptoms. Use normal chewing and seek professional advice for pain or bite concerns.',tips:['Avoid forceful devices.','Do not train through clicking or headaches.','Choose grooming and posture first.']},
  {cat:'Supplements — Complete Database',q:'Can supplements improve my looks quickly?',short:'No supplement creates a fast guaranteed transformation.',answer:'Food, sleep, sunscreen, training and grooming are more important. Supplements can carry side effects, interactions and quality problems.',tips:['Use food-first habits.','Avoid mystery blends.','Ask a clinician or pharmacist first.']},
  {cat:'Mewing & Facial Bone Remodeling',q:'Do facial rollers remove wrinkles or change bone structure?',short:'They do not change bone structure or permanently erase wrinkles.',answer:'A roller can be a pleasant, gentle ritual for some people, but it is not a facial reshaping treatment.',tips:['Use light pressure.','Keep tools clean.','Avoid irritated or acne-prone areas.']}
]);
const addLessons=(id,lessons)=>chapters.find(chapter=>chapter.id===id)?.lessons.push(...lessons);
addLessons('foundations',[
  ['Facial proportions explained','Use proportions as styling references, never as a beauty score.','Compare the whole face in normal light.','Use hair, glasses and facial hair to create balance.'],
  ['Facial symmetry without obsession','Small left-right differences are normal and usually unnoticed.','Check with a relaxed expression in soft daylight.','Focus on grooming and comfort instead of repeated checking.'],
  ['Face shape and glasses','Glasses can frame the face when the width and fit feel natural.','Try frames at normal viewing distance.','Choose comfort over rigid face-shape rules.'],
  ['Face shape and facial hair','Facial hair can frame the lower face without changing anatomy.','Test one conservative length at a time.','Keep lines clean but not artificial.']
]);
addLessons('aesthetics',[
  ['Cheeks and cheekbones','Cheek definition changes with light, expression and surrounding framing.','Use soft directional light in photos.','Avoid dehydration or extreme dieting.'],
  ['Forehead and temple styling','Hair volume, parting and fringe can change upper-face framing.','Choose a style that suits your growth pattern.','Do not hide every feature out of anxiety.'],
  ['Facial expressions that feel natural','A relaxed face reads better than a forced pose.','Relax the jaw, eyes and lips before a photo.','Avoid copying exaggerated online expressions.'],
  ['Camera distance and lens distortion','A close wide lens can distort facial proportions.','Step back and use modest zoom.','Compare photos in consistent lighting.']
]);
addLessons('mewing',[
  ['Facial exercise claims','Exercises may move muscles temporarily but do not predictably sculpt adult bone.','Use gentle mobility only when comfortable.','Stop if you feel jaw pain or headaches.'],
  ['Jaw exerciser safety','Resistance devices can overload the jaw joint and muscles.','Choose normal chewing instead.','Do not train through clicking or pain.'],
  ['The bone-smashing myth','Impact can injure bone, teeth, nerves and joints.','Avoid impact methods completely.','Seek qualified care for real jaw concerns.'],
  ['Nose reshaping tricks','Pressure, clips and massage do not safely reshape adult noses.','Use hair, glasses and camera distance for balance.','Discuss functional concerns with a clinician.']
]);
addLessons('body',[
  ['Comfortable standing posture','Posture is a moving range, not one rigid pose.','Stack head, ribs and pelvis gently.','Move regularly instead of holding tension.'],
  ['Desk-friendly sitting posture','A comfortable setup makes movement easier.','Raise your screen and support your feet.','Change position often.'],
  ['Walking with ease','A relaxed, steady walk improves comfort and presence.','Keep steps natural and eyes forward.','Do not force an exaggerated gait.'],
  ['Core stability basics','A stronger trunk supports movement, not a permanently braced look.','Use controlled movements and breathing.','Progress gradually with good form.'],
  ['Workout recovery','Recovery is part of progress.','Sleep, eat regularly and include easier days.','Do not add training when pain is building.']
]);
addLessons('skin',[
  ['Understanding skin types','Skin can be dry, oily, mixed or sensitive, and can change over time.','Observe clean skin before buying many products.','Choose comfort over a strict label.'],
  ['Moisturizing correctly','Moisturizer supports the skin barrier when skin feels dry or irritated.','Apply a suitable product to slightly damp skin.','Avoid fragranced products if they sting.'],
  ['Product layering order','Simple layering prevents unnecessary irritation.','Apply treatment as directed, then moisturizer and daytime sunscreen.','Do not layer many strong actives together.'],
  ['Morning skincare routine','A practical morning routine can be cleanser if needed, moisturizer and sunscreen.','Keep it quick enough to repeat.','Do not skip sun protection when outdoors.'],
  ['Evening skincare routine','Night is a good time for gentle cleansing and a chosen treatment.','Use one active consistently.','Do not expect overnight results.'],
  ['Shaving without unnecessary irritation','Good technique prevents avoidable bumps and burning.','Soften hair, use lubrication and a clean blade.','Use light passes instead of pressing.']
]);
addLessons('hair',[
  ['Hair washing frequency','Wash based on scalp oil, sweat, flakes and product buildup.','Adjust frequency to comfort and hair type.','Do not follow a rigid internet schedule.'],
  ['Gentle scalp care','Scalp health matters as much as hair styling.','Clean gently and rinse products well.','Seek care for persistent itch, redness or pain.'],
  ['Dandruff: when to get help','Flakes may need scalp-focused treatment or a clinical check.','Follow suitable product labels consistently.','Get help for redness, soreness or shedding.'],
  ['Styling for natural volume','A small amount of suitable product can add shape without stiffness.','Start with less product than you think.','Avoid excessive heat and buildup.'],
  ['Using hair products well','Product choice depends on hair type and finish.','Test one product at a time.','Do not overload hair with oil, wax or spray.'],
  ['Fine-hair styling','Fine hair often benefits from lighter products and a supportive cut.','Dry gently and style with minimal weight.','Avoid heavy layers that flatten it.']
]);
addLessons('grooming',[
  ['The complete shower routine','Basic cleanliness is a high-impact grooming habit.','Wash body and scalp as needed and dry thoroughly.','Avoid harsh scrubbing.'],
  ['Deodorant and odor prevention','Clean skin, clean clothing and suitable deodorant are usually enough.','Apply to clean, dry underarms.','Seek care for sudden strong odor or rash.'],
  ['Hand-care routine','Hands are noticeable in everyday interactions.','Moisturize when dry and keep nails clean.','Do not cut cuticles aggressively.'],
  ['Nail trimming and shaping','Short, clean nails look intentional and reduce snagging.','Trim gradually and file sharp edges.','Do not cut too close to the skin.'],
  ['Foot hygiene','Comfortable, clean feet support daily movement and footwear.','Wash, dry and rotate shoes.','Seek care for persistent pain or skin changes.'],
  ['Fragrance application basics','Fragrance should be subtle and optional.','Use a small amount after washing.','Do not overspray shared spaces.'],
  ['Brushing technique','Gentle, consistent brushing supports oral health and a clean smile.','Use fluoride toothpaste twice daily.','See a dentist for pain or bleeding.'],
  ['Flossing fundamentals','Cleaning between teeth supports gum health where a brush cannot reach.','Use a method that feels comfortable.','Ask a dentist or hygienist for technique help.']
]);
addLessons('routines',[
  ['A 5-minute morning routine','A short routine is easier to keep on busy days.','Brush teeth, wash or refresh, apply sunscreen and choose clean clothes.','Do not make mornings overly complicated.'],
  ['A 10-minute grooming routine','A small weekly reset keeps details under control.','Check nails, facial hair, hair products and outfit readiness.','Do not rush sharp tools.'],
  ['The evening reset','Prepare for tomorrow before sleep.','Set out clothes, clean tools and reduce screens.','Do not sacrifice sleep for more optimization.'],
  ['Professional profile photos','A good profile photo should look like you on a good normal day.','Use soft light, a clean background and normal camera distance.','Avoid heavy filters or misleading edits.'],
  ['Natural social photos','The best social photos look relaxed and context-appropriate.','Use a simple outfit and natural expression.','Do not overpose or over-edit.']
]);
addLessons('mental',[
  ['Avoiding unhealthy comparison','Comparison content can make normal features feel like flaws.','Curate feeds and take breaks when needed.','Do not use other people as your scorecard.'],
  ['Realistic expectations','Presentation changes can be meaningful without transforming anatomy.','Set one observable, kind goal at a time.','Avoid promises of a total transformation.'],
  ['Spotting fake transformations','Before-and-after photos can change through light, lens, pose, weight and editing.','Check whether conditions match.','Do not treat viral images as proof.']
]);
window.AuraMax={chapters,show,chapter,lesson};
const root=document.querySelector('#view-root');
const profileKey='auramax-web-profile';let profile=JSON.parse(localStorage.getItem(profileKey)||'null');
const $=s=>document.querySelector(s); const esc=s=>String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
function profileText(){const text=profile?`${profile.face} face · ${profile.body} body`:'Choose your guide profile';$('#profile-heading').textContent=profile?'Your lookbook is ready.':'A guide built around you.';$('#profile-copy').textContent=profile?`Personalized for a ${text.toLowerCase()}. Use this as a styling guide, never a score.`:'Choose your face shape and body type to start exploring.';}
function openOnboarding(){let step=1,face=profile?.face||'',body=profile?.body||'';const el=$('#onboarding');el.classList.remove('hidden');const faces=[['Oval','M70 16 C38 16 30 47 34 87 C38 124 50 142 70 142 C90 142 102 124 106 87 C110 47 102 16 70 16Z'],['Round','M70 18 C34 18 24 48 29 90 C34 126 49 142 70 142 C91 142 106 126 111 90 C116 48 106 18 70 18Z'],['Square','M37 22 L103 22 L111 61 L106 123 L85 143 L55 143 L34 123 L29 61Z'],['Heart','M27 37 C36 15 104 15 113 37 L102 96 L70 145 L38 96Z'],['Oblong','M48 12 L92 12 C104 33 106 111 92 144 L48 144 C34 111 36 33 48 12Z']];const bodies=['Rectangle','Inverted triangle','Triangle','Oval','Athletic'];function render(){el.innerHTML=`<div class="onboard-shell"><div class="onboard-top"><span class="brand-mark">A</span><b>AuraMax</b><span>Step ${step} of 2</span><button class="text-link" id="onboard-account" type="button">Sign in</button></div>${step===1?`<div class="onboard-panel"><p class="eyebrow">PERSONALISE YOUR GUIDE</p><h1>What is your face shape?</h1><p>Choose the closest visual match. This helps guide hair, glasses and facial-hair suggestions; it does not rate your appearance.</p><div class="choice-grid">${faces.map(([name,path])=>`<button class="choice ${face===name?'selected':''}" data-face="${name}"><svg viewBox="0 0 140 160"><path d="${path}"/></svg><b>${name}</b><small>Choose the closest match</small></button>`).join('')}</div><button class="button primary" id="next" ${!face?'disabled':''}>Continue</button></div>`:`<div class="onboard-panel"><p class="eyebrow">PERSONALISE YOUR GUIDE</p><h1>Which body type is closest?</h1><p>This is for fit and silhouette ideas, not a health assessment. Choose the closest match today.</p><div class="choice-grid">${bodies.map((name,i)=>`<button class="choice body ${body===name?'selected':''}" data-body="${name}"><svg viewBox="0 0 120 150"><circle cx="60" cy="22" r="13"/><path d="${i===1?'M36 44 L84 44 L76 125 L44 125Z':i===2?'M47 44 L73 44 L91 125 L29 125Z':i===3?'M38 44 L82 44 L89 110 L78 128 L42 128 L31 110Z':'M43 44 L77 44 L76 126 L44 126Z'}"/></svg><b>${name}</b><small>Choose the closest match</small></button>`).join('')}</div><div class="onboard-actions"><button class="back-button" id="back">Back</button><button class="button primary" id="enter" ${!body?'disabled':''}>Enter AuraMax</button></div></div>`}</div>`;el.querySelectorAll('[data-face]').forEach(b=>b.onclick=()=>{face=b.dataset.face;render()});el.querySelectorAll('[data-body]').forEach(b=>b.onclick=()=>{body=b.dataset.body;render()});el.querySelector('#next')?.addEventListener('click',()=>{step=2;render()});el.querySelector('#back')?.addEventListener('click',()=>{step=1;render()});el.querySelector('#onboard-account')?.addEventListener('click',()=>{el.classList.add('hidden');window.dispatchEvent(new CustomEvent('auramax:open-account'));});el.querySelector('#enter')?.addEventListener('click',()=>{profile={face,body};localStorage.setItem(profileKey,JSON.stringify(profile));el.classList.add('hidden');profileText();show('hub')})}render()}
function show(view){document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='hub')root.innerHTML=`<div class="view-head"><div><p class="eyebrow">EXPLORE AURAMAX</p><h2>Where do you want to start?</h2></div><p>Choose one path. Each section is designed for clear, useful reading without overwhelm.</p></div><div class="chapter-grid category-hub"><button class="chapter-card" data-view="quick"><small>01 · QUICK START</small><h3>Quick Looksmax Tips & Techniques</h3><p>Short, practical actions for grooming, skin, hair, posture and presentation.</p></button><button class="chapter-card" data-view="qa"><small>02 · ASK & LEARN</small><h3>LooksMax Q & A Advanced</h3><p>Searchable answers, tips, do/don’t guidance and common mistakes.</p></button><button class="chapter-card" data-view="style"><small>03 · DRESS BETTER</small><h3>Styling Guide</h3><p>Fit, colour, wardrobe essentials, footwear and outfit formulas.</p></button><button class="chapter-card complete-guide" data-view="lookbook"><small>04 · READ THE BOOK</small><h3>LooksMax Complete Guide</h3><p>Open the complete guide, then navigate chapter by chapter into lessons.</p></button></div>`;else if(view==='lookbook')root.innerHTML=`<div class="view-head"><div><p class="eyebrow">LOOKSMAX COMPLETE GUIDE</p><h2>Choose a chapter.</h2></div><p>Read a short, practical lesson at a time. Save the ideas that fit your real routine.</p></div><div class="chapter-grid">${chapters.map(c=>`<button class="chapter-card" data-chapter="${c.id}"><small>CHAPTER ${c.tag}</small><h3>${c.name}</h3><p>${c.desc}</p></button>`).join('')}</div>`;else if(view==='qa')renderQA();else if(view==='quick')renderQuick();else if(view==='style')root.innerHTML=`<div class="view-head"><div><p class="eyebrow">STYLING GUIDE</p><h2>Dress with intention.</h2></div><p>Start with fit, build a practical base and use colour or accessories to refine.</p></div><div class="style-grid">${styleCards.map(([t,items])=>`<article class="style-card"><h3>${t}</h3><ul>${items.map(x=>`<li>${x}</li>`).join('')}</ul></article>`).join('')}</div>`;root.querySelectorAll('[data-chapter]').forEach(b=>b.onclick=()=>chapter(b.dataset.chapter));root.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>show(b.dataset.view));root.scrollIntoView({behavior:'smooth',block:'start'})}
function chapter(id){const c=chapters.find(x=>x.id===id);root.innerHTML=`<button class="text-link back">← All chapters</button><div class="view-head"><div><p class="eyebrow">CHAPTER ${c.tag}</p><h2>${c.name}</h2></div><p>${c.desc}</p></div><div class="lesson-list">${c.lessons.map((l,i)=>`<button class="lesson-card" data-lesson="${i}"><small>LESSON ${String(i+1).padStart(2,'0')}</small><h3>${l[0]}</h3><p>${l[1]}</p></button>`).join('')}</div>`;root.querySelector('.back').onclick=()=>show('lookbook');root.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>lesson(c,b.dataset.lesson));root.scrollIntoView({behavior:'smooth',block:'start'})}
function lesson(c,index){const l=c.lessons[index];root.innerHTML=`<article class="reader"><button class="text-link back">← ${c.name}</button><p class="eyebrow">CHAPTER ${c.tag} · LESSON ${String(+index+1).padStart(2,'0')}</p><h1>${l[0]}</h1><p class="lead">${l[1]}</p><section><h3>What to do</h3><ol><li>${l[2]}</li><li>${l[3]}</li><li>Review the result in normal conditions and keep only what is comfortable and repeatable.</li></ol></section><section><h3>Remember</h3><p>Use this guide to improve presentation and wellbeing, not to chase impossible perfection. Seek qualified help for pain, sudden changes or persistent symptoms.</p></section></article>`;root.querySelector('.back').onclick=()=>chapter(c.id);root.scrollIntoView({behavior:'smooth',block:'start'})}
function renderQuick(query='',keepFocus=false){const filtered=quickTips.filter(([,title,text])=>`${title} ${text}`.toLowerCase().includes(query.toLowerCase()));root.innerHTML=`<button class="text-link back" data-view="hub">← Back to categories</button><div class="view-head"><div><p class="eyebrow">QUICK LOOKSMAX TIPS & TECHNIQUES</p><h2>Small details. Clear actions.</h2></div><p>Search a specific concern and get a short, useful answer without reading a long article.</p></div><div class="qa-toolbar"><input class="search quick-search" value="${esc(query)}" placeholder="Search skin, hair, jaw, posture, sleep…"></div><p class="qa-meta">${filtered.length} matching tips</p><div class="tips-grid">${filtered.map(([n,t,d])=>`<article class="tip-card"><span class="tip-number">${n}</span><h3>${t}</h3><p>${d}</p></article>`).join('')||'<p>No tip found. Try a broader keyword such as skin, hair, outfit or sleep.</p>'}</div>`;root.querySelector('.back').onclick=()=>show('hub');const input=root.querySelector('.quick-search');input.oninput=()=>renderQuick(input.value,true);if(keepFocus){input.focus();input.setSelectionRange(input.value.length,input.value.length)}}
function renderQA(query='',keepFocus=false){const filtered=faqs.filter(x=>`${x.cat} ${x.q} ${x.answer}`.toLowerCase().includes(query.toLowerCase())).slice(0,80);const card=(x,index,full=true)=>`<article class="qa-card"><details><summary><span class="qa-number">Q${String(index+1).padStart(3,'0')}</span>${x.q}</summary><span class="qa-meta">${x.cat}</span><p><b>${x.short}</b></p><p>${x.answer}</p>${full?`<p><b>Key tips:</b></p><ul>${x.tips.map(t=>`<li>${t}</li>`).join('')}</ul>`:''}</details></article>`;root.innerHTML=`<button class="text-link back" data-view="hub">← Back to categories</button><div class="view-head"><div><p class="eyebrow">LOOKSMAX Q&A</p><h2>Ask the practical question.</h2></div><p>500 concise answers across grooming, style, health, photography and confidence.</p></div><div class="qa-toolbar"><input class="search" value="${esc(query)}" placeholder="Search jawline, acne, haircut, outfit, sleep…"></div><div class="filters">${['All',...chapters.map(c=>c.name)].map(c=>`<button class="filter ${c==='All'?'active':''}" data-cat="${c}">${c}</button>`).join('')}</div><div class="qa-grid">${filtered.map((x,index)=>card(x,index)).join('')}</div>`;root.querySelector('.back').onclick=()=>show('hub');const input=root.querySelector('.search');input.oninput=()=>renderQA(input.value,true);input.focus();if(keepFocus){input.setSelectionRange(input.value.length,input.value.length)}root.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{const cat=b.dataset.cat;const hits=cat==='All'?faqs:faqs.filter(x=>x.cat===cat);root.querySelector('.qa-grid').innerHTML=hits.slice(0,80).map((x,index)=>card(x,index,false)).join('');root.querySelectorAll('.filter').forEach(x=>x.classList.toggle('active',x===b))})}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>show(b.dataset.view)));$('#profile-button').onclick=openOnboarding;$('#edit-profile').onclick=openOnboarding;profileText();if(profile)$('#onboarding').classList.add('hidden');else openOnboarding();show('hub');
